import{_ as a,o as t,c as n,ae as i}from"./chunks/framework.Co1PSFSm.js";const g=JSON.parse('{"title":"Arquitectura y Seguridad","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),s={name:"reference/index.md"};function d(l,e,r,o,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="arquitectura-y-seguridad" tabindex="-1">Arquitectura y Seguridad <a class="header-anchor" href="#arquitectura-y-seguridad" aria-label="Permalink to &quot;Arquitectura y Seguridad&quot;">​</a></h1><h2 id="arquitectura-de-seguridad-v14" tabindex="-1">Arquitectura de Seguridad (V14) <a class="header-anchor" href="#arquitectura-de-seguridad-v14" aria-label="Permalink to &quot;Arquitectura de Seguridad (V14)&quot;">​</a></h2><h3 id="_1-fingerprint-hibrido-anti-clonado" tabindex="-1">1. Fingerprint Híbrido Anti-Clonado <a class="header-anchor" href="#_1-fingerprint-hibrido-anti-clonado" aria-label="Permalink to &quot;1. Fingerprint Híbrido Anti-Clonado&quot;">​</a></h3><p>Cada agente genera una identidad única e irrepetible al instalarse:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fingerprint = SHA256(machine-id + disk_serial_or_uuid + hostname)</span></span></code></pre></div><p>Esta huella se envía en <strong>cada latido</strong> (<code>X-Agent-Fingerprint</code>). Si no coincide con la registrada al activar el token, el API rechaza la conexión, previniendo clonación de licencias.</p><h3 id="_2-ciclo-de-vida-del-token-saas" tabindex="-1">2. Ciclo de Vida del Token SaaS <a class="header-anchor" href="#_2-ciclo-de-vida-del-token-saas" aria-label="Permalink to &quot;2. Ciclo de Vida del Token SaaS&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WHMCS Provisión → Token generado (dbp_saas_XXXX)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Estado: pending (válido 48h)</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Cliente instala → Token se vincula al hardware</span></span>
<span class="line"><span>Estado: activated</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Si pasan 48h sin instalar → Estado: expired</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Admin puede revocar → Estado: revoked</span></span></code></pre></div><h3 id="_3-capas-de-seguridad" tabindex="-1">3. Capas de Seguridad <a class="header-anchor" href="#_3-capas-de-seguridad" aria-label="Permalink to &quot;3. Capas de Seguridad&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Capa</th><th style="text-align:left;">Tecnología</th><th style="text-align:left;">Detalle</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Data at Rest</strong></td><td style="text-align:left;">AES-256-GCM</td><td style="text-align:left;">Credenciales S3 cifradas en DB con llave maestra de 32 bytes</td></tr><tr><td style="text-align:left;"><strong>Data in Transit</strong></td><td style="text-align:left;">TLS 1.3</td><td style="text-align:left;">Toda comunicación Agente ↔ API</td></tr><tr><td style="text-align:left;"><strong>Autenticación</strong></td><td style="text-align:left;">Triple Token</td><td style="text-align:left;">X-Agent-ID + X-Agent-Key + X-Agent-Fingerprint en cada request</td></tr><tr><td style="text-align:left;"><strong>Imagen Docker</strong></td><td style="text-align:left;">GHCR Privado</td><td style="text-align:left;">Cliente nunca ve el código fuente</td></tr><tr><td style="text-align:left;"><strong>PAT GHCR</strong></td><td style="text-align:left;">Controlado</td><td style="text-align:left;">Token de descarga nunca expuesto al cliente</td></tr></tbody></table><h2 id="sandbox-test-verificacion-inmune" tabindex="-1">Sandbox Test (Verificación Inmune) <a class="header-anchor" href="#sandbox-test-verificacion-inmune" aria-label="Permalink to &quot;Sandbox Test (Verificación Inmune)&quot;">​</a></h2><p>Planes Enterprise ejecutan validaciones en redes aisladas para confirmar que un backup no solo descomprime bien, sino que las bases de datos levantan exitosamente.</p>`,12)])])}const h=a(s,[["render",d]]);export{g as __pageData,h as default};
